const items = $input.all();

const results = [];

for (const item of items) {
  const body = item.json.body || item.json;

  const contractId = body.contract_id;
  const contractText = body.contract_text;

  const errors = [];

  if (!contractId || typeof contractId !== 'string' || contractId.trim() === '') {
    errors.push('contract_id is required and must be a non-empty string');
  }

  if (!contractText || typeof contractText !== 'string') {
    errors.push('contract_text is required and must be a string');
  } else if (contractText.trim().length < 20) {
    errors.push('contract_text is too short to be a usable contract');
  } else if (contractText.length > 100000) {
    errors.push('contract_text exceeds maximum allowed length');
  }

  if (errors.length > 0) {
    results.push({
      json: {
        valid: false,
        errors,
        contract_id: contractId || null
      }
    });
  } else {
    results.push({
      json: {
        valid: true,
        contract_id: contractId.trim(),
        contract_text: contractText.trim()
      }
    });
  }
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Gemini response ko parse karo
  let extracted;
  try {
    const rawText =
    data?.content?.parts?.[0]?.text ??                    // ← Gemini node ka actual shape
    data?.candidates?.[0]?.content?.parts?.[0]?.text ??   // ← native API fallback
    data?.text ??                                          // ← plain text fallback
    null;

    if (rawText === null) {
      throw new Error('No text found in Gemini response');
    }

    // Markdown fence strip karo agar hai
    const cleaned = String(rawText)
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/```$/i, '')
      .trim();

    extracted = JSON.parse(cleaned);
  } catch (err) {
    results.push({
      json: {
        valid: false,
        errors: [`MALFORMED_GEMINI_OUTPUT: ${err.message}`]
      }
    });
    continue;
  }

  const errors = [];

  // ---------- VENDOR ----------
  const vendor =
    typeof extracted.vendor === 'string' && extracted.vendor.trim() !== ''
      ? extracted.vendor.trim()
      : null;

  if (!vendor) {
    errors.push('vendor is missing or invalid');
  }

  // ---------- RENEWAL DATE ----------
  const renewalDateRaw =
    typeof extracted.renewal_date === 'string'
      ? extracted.renewal_date.trim()
      : null;

  let renewalDate = null;

  if (!renewalDateRaw) {
    errors.push('renewal_date is missing');
  } else if (!/^\d{4}-\d{2}-\d{2}$/.test(renewalDateRaw)) {
    errors.push('renewal_date must use YYYY-MM-DD format');
  } else {
    const d = new Date(`${renewalDateRaw}T00:00:00Z`);
    if (Number.isNaN(d.getTime())) {
      errors.push('renewal_date is not a valid calendar date');
    } else {
      renewalDate = renewalDateRaw;
    }
  }

  // ---------- NOTICE PERIOD ----------
  const noticeRaw = extracted.notice_period_days;

  let noticePeriod = NaN;

  if (typeof noticeRaw === 'number') {
    noticePeriod = noticeRaw;
  } else if (typeof noticeRaw === 'string' && noticeRaw.trim() !== '') {
    noticePeriod = Number(noticeRaw);
  }

  if (!Number.isFinite(noticePeriod) || noticePeriod < 0 || !Number.isInteger(noticePeriod)) {
    errors.push('notice_period_days must be a non-negative integer');
  }

  // ---------- AUTO RENEWAL ----------
  const autoRenewal = extracted.auto_renewal;

  if (typeof autoRenewal !== 'boolean') {
    errors.push('auto_renewal must be true or false');
  }

  // ---------- ANNUAL VALUE ----------
  const valueRaw = extracted.annual_value;

  let annualValue = NaN;

  if (typeof valueRaw === 'number') {
    annualValue = valueRaw;
  } else if (typeof valueRaw === 'string' && valueRaw.trim() !== '') {
    annualValue = Number(valueRaw.replace(/[$,]/g, ''));
  }

  if (!Number.isFinite(annualValue) || annualValue < 0) {
    errors.push('annual_value must be a non-negative number');
  }

  // ---------- RESULT ----------
  if (errors.length > 0) {
    results.push({
      json: {
        valid: false,
        errors
      }
    });
  } else {
    results.push({
      json: {
        valid: true,
        vendor,
        renewal_date: renewalDate,
        notice_period_days: noticePeriod,
        auto_renewal: autoRenewal,
        annual_value: annualValue
      }
    });
  }
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  const errors = [];

  const renewalDate = data.renewal_date;
  const noticePeriod = Number(data.notice_period_days);

  // ---------- Validate calculation inputs ----------
  if (!renewalDate || !/^\d{4}-\d{2}-\d{2}$/.test(renewalDate)) {
    errors.push('renewal_date must be in YYYY-MM-DD format');
  }

  if (!Number.isFinite(noticePeriod) || noticePeriod < 0) {
    errors.push('notice_period_days must be a non-negative number');
  }

  if (errors.length > 0) {
    results.push({
      json: {
        valid: false,
        calculation_status: 'FAILED',
        errors
      }
    });
    continue;
  }

  // ---------- Convert ISO date → UTC day (timezone-safe) ----------
  function isoToUtcDay(isoDate) {
    const [year, month, day] = isoDate.split('-').map(Number);
    return Date.UTC(year, month - 1, day);
  }

  // ---------- Calculate notice deadline ----------
  const millisecondsPerDay = 24 * 60 * 60 * 1000;
  const renewalTimestamp = isoToUtcDay(renewalDate);
  const deadlineTimestamp = renewalTimestamp - (noticePeriod * millisecondsPerDay);

  const noticeDeadline = new Date(deadlineTimestamp)
    .toISOString()
    .slice(0, 10);

  // ---------- Today (calendar date, UTC) ----------
  const now = new Date();
  const todayUtc = Date.UTC(
    now.getUTCFullYear(),
    now.getUTCMonth(),
    now.getUTCDate()
  );

  // ---------- Days remaining ----------
  const daysUntilDeadline = Math.round(
    (deadlineTimestamp - todayUtc) / millisecondsPerDay
  );

  results.push({
    json: {
      valid: true,
      calculation_status: 'SUCCESS',

      vendor: data.vendor,
      renewal_date: renewalDate,
      notice_period_days: noticePeriod,
      notice_deadline: noticeDeadline,
      days_until_deadline: daysUntilDeadline,

      auto_renewal: data.auto_renewal,
      annual_value: Number(data.annual_value)
    }
  });
}

return results;

const items = $input.all();
const results = [];
const contractId = $('Validate Contract Input').first().json.contract_id;
for (const item of items) {
  const data = item.json;

  const errors = [];

  const daysUntilDeadline = Number(data.days_until_deadline);
  const annualValue = Number(data.annual_value);
  const autoRenewal = data.auto_renewal;

  if (!Number.isFinite(daysUntilDeadline)) {
    errors.push('days_until_deadline is invalid');
  }

  if (!Number.isFinite(annualValue) || annualValue < 0) {
    errors.push('annual_value is invalid');
  }

  if (typeof autoRenewal !== 'boolean') {
    errors.push('auto_renewal must be true or false');
  }

  if (errors.length > 0) {
    results.push({
      json: {
        valid: false,
        risk_status: 'MANUAL_REVIEW',
        errors
      }
    });
    continue;
  }

  let riskStatus;
  let riskReason;

  // Rule 1 — URGENT
  if (
    autoRenewal === true &&
    daysUntilDeadline <= 30 &&
    annualValue >= 10000
  ) {
    riskStatus = 'URGENT_REVIEW';
    riskReason =
      'Auto-renewing contract has a notice deadline within 30 days and annual value is at least $10,000.';
  }
  // Rule 2 — MONITOR
  else if (
    autoRenewal === true &&
    daysUntilDeadline <= 90
  ) {
    riskStatus = 'MONITOR';
    riskReason =
      'Auto-renewing contract has a notice deadline within 90 days.';
  }
  // Rule 3 — NO_ACTION
  else {
    riskStatus = 'NO_ACTION';
    riskReason =
      'Contract does not currently meet the escalation or monitoring thresholds.';
  }

  results.push({
    json: {
      valid: true,
      contract_id: contractId,
      vendor: data.vendor,
      renewal_date: data.renewal_date,
      notice_period_days: data.notice_period_days,
      notice_deadline: data.notice_deadline,
      days_until_deadline: daysUntilDeadline,

      auto_renewal: autoRenewal,
      annual_value: annualValue,

      risk_status: riskStatus,
      risk_reason: riskReason
    }
  });
}

return results;

